set
  html_template = $fmsi137_html$<!DOCTYPE html><html><head><meta charset="utf-8"/><meta http-equiv="Content-Type" content="text/html; charset=UTF-8"/><meta name="viewport" content="width=device-width,initial-scale=1"/><title>You&apos;re invited to a practical mentorship session</title></head><body style="margin:0;padding:0;background-color:#F8FAFC;font-family:Arial,Helvetica,sans-serif;color:#111827;-webkit-text-size-adjust:100%;"><div style="display:none;max-height:0;overflow:hidden;mso-hide:all;font-size:1px;line-height:1px;color:transparent;opacity:0;">{{email_preheader_text}}</div><table role="presentation" width="100%" cellspacing="0" cellpadding="0" border="0" bgcolor="#F8FAFC" style="background-color:#F8FAFC;mso-table-lspace:0;mso-table-rspace:0;"><tr><td align="center" style="padding:24px 12px;"><table role="presentation" width="100%" cellspacing="0" cellpadding="0" border="0" bgcolor="#ffffff" style="max-width:680px;background-color:#ffffff;border:1px solid #E5E7EB;border-radius:10px;mso-table-lspace:0;mso-table-rspace:0;"><tr><td bgcolor="#FFFFFF" style="background-color:#FFFFFF;border-bottom:2px solid #F59E0B;padding:22px 24px;"><table role="presentation" width="100%" cellspacing="0" cellpadding="0" border="0" bgcolor="#FFFFFF" style="background-color:#FFFFFF;width:100%;mso-table-lspace:0;mso-table-rspace:0;"><tr><td width="52" valign="middle" bgcolor="#FFFFFF" style="background-color:#FFFFFF;padding:0 12px 0 0;vertical-align:middle;"><img src="{{email_logo_url}}" width="48" height="48" alt="NextGen CTO Logo" style="width:48px;height:auto;display:block;border:0;border-radius:8px;outline:none;text-decoration:none;"/></td><td valign="middle" bgcolor="#FFFFFF" style="background-color:#FFFFFF;color:#1E3A8A;font-size:18px;font-weight:800;line-height:1.25;padding:0;vertical-align:middle;">{{email_header_display}}</td></tr></table></td></tr><tr><td bgcolor="#ffffff" style="background-color:#FFFFFF;padding:20px 22px 24px 22px;"><p style="margin:0 0 8px 0;font-size:12px;font-weight:700;color:#F59E0B;text-transform:uppercase;letter-spacing:0.08em;">Mentorship Session</p><h1 style="margin:0 0 10px 0;font-size:26px;line-height:1.25;color:#0F172A;font-weight:800;">You&apos;re invited to a practical mentorship session</h1><table role="presentation" width="100%" cellspacing="0" cellpadding="0" border="0" style="margin:0 0 18px 0;"><tr><td height="2" bgcolor="#F59E0B" style="background-color:#F59E0B;font-size:0;line-height:0;">&nbsp;</td></tr></table><p style="margin:0 0 14px 0;font-size:15px;line-height:1.7;color:#334155;">Hi <strong>{{first_name}}</strong>,</p><table role="presentation" cellspacing="0" cellpadding="0" border="0" style="margin:0 0 22px 0;"><tr><td align="left"><a href="{{cta_url}}" style="display:inline-block;background:linear-gradient(135deg,#e58c33 0%,#d97a1f 100%);color:#FFFFFF;text-decoration:none;font-family:Arial,Helvetica,sans-serif;font-size:16px;font-weight:700;padding:14px 22px;border-radius:50px;box-shadow:0 6px 20px rgba(229,140,51,0.35);letter-spacing:0.5px;">{{cta_label}}</a></td></tr></table><p style="margin:0 0 12px 0;font-size:15px;line-height:1.7;color:#334155;">You are invited to a mentorship session with {{mentor_name}}.</p><p style="margin:0 0 12px 0;font-size:15px;line-height:1.7;color:#334155;">This session is meant to be practical, direct, and useful &mdash; not a long motivational lecture.</p><p style="margin:0 0 8px 0;font-size:15px;line-height:1.7;color:#334155;">You will get clarity on how to think about your career readiness journey and what to focus on next:</p><ul style="margin:0 0 18px 0;padding-left:18px;"><li style="margin:0 0 8px 0;font-size:14px;line-height:1.6;color:#334155;">What to prioritize first</li><li style="margin:0 0 8px 0;font-size:14px;line-height:1.6;color:#334155;">How to avoid random learning</li><li style="margin:0 0 8px 0;font-size:14px;line-height:1.6;color:#334155;">How to build better project proof</li><li style="margin:0 0 8px 0;font-size:14px;line-height:1.6;color:#334155;">How to improve your Resume, GitHub, and LinkedIn</li><li style="margin:0 0 8px 0;font-size:14px;line-height:1.6;color:#334155;">How to prepare with more confidence for interviews</li><li style="margin:0 0 0px 0;font-size:14px;line-height:1.6;color:#334155;">How to use AI, fundamentals, and projects together</li></ul><table role="presentation" width="100%" cellspacing="0" cellpadding="0" border="0" style="margin:0 0 18px 0;background-color:#F8FAFC;border:1px solid #E2E8F0;border-radius:12px;"><tr><td style="padding:14px 16px;"><p style="margin:0 0 8px 0;font-size:14px;font-weight:700;color:#0F172A;">Session details</p><p style="margin:0 0 6px 0;font-size:14px;line-height:1.6;color:#334155;">Date: {{session_date}}</p><p style="margin:0 0 6px 0;font-size:14px;line-height:1.6;color:#334155;">Time: {{session_time}}</p><p style="margin:0;font-size:14px;line-height:1.6;color:#334155;">Zoom Link: <a href="{{zoom_meeting_url}}" style="color:#2563EB;text-decoration:underline;">{{zoom_meeting_url}}</a></p></td></tr></table><p style="margin:0 0 12px 0;font-size:15px;line-height:1.7;color:#334155;">Come with a learner mindset.</p><p style="margin:0 0 16px 0;font-size:15px;line-height:1.7;color:#334155;">You do not need to have everything figured out. You just need to be serious about improving step by step.</p><p style="margin:0 0 6px 0;font-size:15px;font-weight:700;color:#0F172A;">Need help before the session?</p><p style="margin:0 0 8px 0;font-size:15px;line-height:1.7;color:#334155;">Use the support channel here: <a href="{{support_url}}" style="color:#F4A854;text-decoration:none;font-weight:600;">{{support_url}}</a></p><p style="margin:0 0 12px 0;font-size:14px;line-height:1.6;color:#64748B;">You are receiving this email because you are a subscriber of NextGen CTO.</p><p style="margin:0;font-size:14px;line-height:1.6;color:#64748B;">Unsubscribe or manage preferences:<br/><a href="{{unsubscribe_url}}" style="color:#64748B;text-decoration:underline;">{{unsubscribe_url}}</a></p></td></tr><tr><td align="center" bgcolor="#ffffff" style="text-align:center;margin-top:50px;font-size:0.9em;color:#777;padding:25px 20px;background:#ffffff;background-color:#ffffff;"><table role="presentation" cellspacing="0" cellpadding="0" border="0" align="center" style="margin:0 auto;"><tr><td valign="middle" style="padding-right:10px;"><a href="{{email_website_url}}" target="_blank" rel="noopener noreferrer" style="text-decoration:none;"><img src="{{email_logo_url}}" alt="NextGen CTO" width="56" style="display:block;border:0;outline:none;text-decoration:none;height:auto;"/></a></td><td valign="middle" style="font-family:Arial,Helvetica,sans-serif;font-size:18px;font-weight:700;line-height:1.2;color:#1E335C;">NextGen CTO</td></tr></table><div style="margin:auto;text-align:center;"><p style="color:#172B4D;font-size:14px;font-weight:600;">Follow us on</p><table role="presentation" cellspacing="0" cellpadding="0" border="0" align="center" style="margin:0 auto;"><tr><td style="padding:0 6px;"><a href="https://www.instagram.com/code.with.ctobhaiya?igsh=MTgyM3ZyY2V6enJheQ==" style="cursor:pointer;text-decoration:none;"><img src="https://algozenith.s3.ap-south-1.amazonaws.com/content/07-06-24/8059_a58afaf2-29b8-4761-9c0e-6d9fc6ae6f4a.png" style="width:40px;height:40px;" alt="Instagram"/></a></td><td style="padding:0 6px;"><a href="https://www.linkedin.com/in/anuj-kumar-a-k-a-cto-bhaiya-on-youtube-9a188968/" style="cursor:pointer;text-decoration:none;"><img src="https://algozenith.s3.ap-south-1.amazonaws.com/content/07-06-24/8059_44a6715c-441d-43f8-b5ee-bad637d717d3.png" style="width:40px;height:40px;" alt="LinkedIn"/></a></td><td style="padding:0 6px;"><a href="https://www.youtube.com/@CodingwithCTOBhaiya" style="cursor:pointer;text-decoration:none;"><img src="https://algozenith.s3.ap-south-1.amazonaws.com/content/07-06-24/8059_11a31c49-ba39-442b-81ac-b0816e2a71a1.png" style="width:40px;height:40px;" alt="YouTube"/></a></td></tr></table></div><div style="flex-grow:1;height:1px;background-color:black;margin-top:2rem;"></div><p style="font-weight:300;margin:0;padding:0;text-align:center;font-size:15px;">If you are no longer interested, click <a href="{{unsubscribe_url}}">here</a> to unsubscribe.</p><p style="font-weight:300;margin-top:6px;text-align:center;font-size:15px;">&copy; Copyright 2025. NextGen CTO Pvt Ltd. All Rights Reserved.</p></td></tr></table></td></tr></table></body></html>$fmsi137_html$,
  text_template = $fmsi137_txt$You're invited to a practical mentorship session

Hi {{first_name}},

You are invited to a mentorship session with {{mentor_name}}.

This session is meant to be practical, direct, and useful — not a long motivational lecture.

You will get clarity on how to think about your career readiness journey and what to focus on next:

What to prioritize first
How to avoid random learning
How to build better project proof
How to improve your Resume, GitHub, and LinkedIn
How to prepare with more confidence for interviews
How to use AI, fundamentals, and projects together

Session details:

Date: {{session_date}}
Time: {{session_time}}
Zoom Link: {{zoom_meeting_url}}

Come with a learner mindset.

You do not need to have everything figured out. You just need to be serious about improving step by step.

{{cta_label}}: {{cta_url}}

Need help before the session?

Use the support channel here: {{support_url}}

You are receiving this email because you are a subscriber of NextGen CTO.

Unsubscribe or manage preferences:
{{unsubscribe_url}}$fmsi137_txt$,
  variables = '[{"key":"email_logo_url","label":"Brand logo URL","required":false,"sample":"https://www.nextgen-cto.in/assets/logo-hd.png","inputType":"url","source":"system","helpText":"Public HTTPS URL from EMAIL_BRAND_LOGO_URL or NEXT_PUBLIC_EMAIL_BRAND_LOGO_URL."},{"key":"first_name","label":"Recipient first name","required":false,"sample":"Anuj","inputType":"text","source":"recipient"},{"key":"college_name","label":"College name","required":false,"sample":"MAIT","inputType":"text","source":"recipient"},{"key":"mentor_name","label":"Mentor name","required":true,"sample":"Anuj Kumar","inputType":"text","source":"campaign"},{"key":"session_date","label":"Session date","required":true,"sample":"15 May 2025","inputType":"date","source":"campaign"},{"key":"session_time","label":"Session time","required":true,"sample":"4:00 PM","inputType":"time","source":"campaign"},{"key":"zoom_meeting_url","label":"Zoom meeting URL","required":true,"placeholder":"https://...","inputType":"url","source":"campaign"},{"key":"cta_url","label":"CTA URL","required":true,"placeholder":"https://...","inputType":"url","source":"campaign"},{"key":"cta_label","label":"CTA button text","required":true,"sample":"Confirm your spot","inputType":"text","source":"campaign"},{"key":"support_url","label":"Support URL","required":true,"placeholder":"https://...","inputType":"url","source":"campaign"},{"key":"unsubscribe_url","label":"Unsubscribe URL","required":false,"inputType":"url","source":"system","helpText":"System-generated on send. Preview-only in Email Center."}]'::jsonb,
